-- 1. INSERT 50 USERS
ON CONFLICT (email) DO NOTHING;

-- 2. INSERT 50 STUDENT PROFILES
ON CONFLICT (user_id) DO NOTHING;

-- 3. INSERT ENROLLMENTS FOR 50 STUDENTS
ON CONFLICT (user_id, course_id) DO NOTHING;

-- 4. INSERT STUDENT GRADES FOR ICTU COURSE SECTIONS
ON CONFLICT (section_id, student_id) DO NOTHING;

-- Update current_enrolled count in course_sections
UPDATE course_sections SET current_enrolled = (SELECT COUNT(*) FROM student_grades WHERE section_id = course_sections.id);